public static int calculateTimeNeeded(int N) {
    // For less than 3 people, no time is needed to reverse the seating order.
    if (N < 3) {
        return 0;
    }
    // The time needed grows linearly: 2 minutes for 4 people, 4 minutes for 5 people, etc.
    // Formula: time = 2 * (N - 3) = 2N - 6
    long result = 2L * N - 6;
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    class Backtrack {
        void dfs() {
            if (current.size() == nums.length) {
                res.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < nums.length; i++) {
                if (used[i]) continue;
                used[i] = true;
                current.add(nums[i]);
                dfs();
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }
    new Backtrack().dfs();
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Replace null strings with empty strings
    for (int i = 0; i < strings.size(); i++) {
        if (strings.get(i) == null) {
            strings.set(i, "");
        }
    }
    // Find the minimum length among all strings
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    String revFirst = new StringBuilder(first).reverse().toString();
    // Try lengths from minLen down to 1
    for (int len = minLen; len >= 1; len--) {
        // Collect all candidate substrings of this length from first string and its reverse
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            candidates.add(first.substring(i, i + len));
        }
        for (int i = 0; i <= revFirst.length() - len; i++) {
            candidates.add(revFirst.substring(i, i + len));
        }
        // Check each candidate
        for (String cand : candidates) {
            String revCand = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(revCand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

