public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }

    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }

    StringBuilder result = new StringBuilder(n);

    while (result.length() < n) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = freq.firstEntry();
        if (entry == null) {
            break;
        }
        char last = entry.getKey();
        result.append(last);
        int count = entry.getValue() - 1;
        if (count == 0) {
            freq.remove(last);
        } else {
            freq.put(last, count);
        }

        while (true) {
            java.util.Map.Entry<Character, Integer> nextEntry = freq.higherEntry(last);
            if (nextEntry == null) {
                break;
            }
            last = nextEntry.getKey();
            result.append(last);
            count = nextEntry.getValue() - 1;
            if (count == 0) {
                freq.remove(last);
            } else {
                freq.put(last, count);
            }
        }

        // Descending phase
        entry = freq.lastEntry();
        if (entry == null) {
            break;
        }
        last = entry.getKey();
        result.append(last);
        count = entry.getValue() - 1;
        if (count == 0) {
            freq.remove(last);
        } else {
            freq.put(last, count);
        }

        while (true) {
            java.util.Map.Entry<Character, Integer> prevEntry = freq.lowerEntry(last);
            if (prevEntry == null) {
                break;
            }
            last = prevEntry.getKey();
            result.append(last);
            count = prevEntry.getValue() - 1;
            if (count == 0) {
                freq.remove(last);
            } else {
                freq.put(last, count);
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0L);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (Long sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) {
            continue;
        }
        long target = prod / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i (top is step n)
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp[i - 1] + cost[i - 1];
        int costFromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

