public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    // If k is too large, 2^k would exceed reasonable memory limits
    if (k > 20) { // 2^20 = 1,048,576, which is manageable
        return false;
    }
    int totalCodes = 1 << k;
    if (s.length() < totalCodes) {
        return false;
    }
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int curr = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // Invalid character in binary string
            return false;
        }
        curr = ((curr << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

