public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long currentMax = nums[0];
    long currentMin = nums[0];
    long globalMax = nums[0];
    long globalMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        currentMax = Math.max(val, currentMax + val);
        globalMax = Math.max(globalMax, currentMax);
        currentMin = Math.min(val, currentMin + val);
        globalMin = Math.min(globalMin, currentMin);
    }
    long result = Math.max(globalMax, -globalMin);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    List<Long> fib = new ArrayList<>();
    fib.add(1L);
    fib.add(1L);
    while (true) {
        long next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }
    int count = 0;
    int idx = fib.size() - 1;
    int remaining = k;
    while (remaining > 0) {
        while (fib.get(idx) > remaining) {
            idx--;
        }
        remaining -= fib.get(idx).intValue();
        count++;
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k - 1 < factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public String makeGood(String s) {
