    int[] max = new int[1];
    class Solver {
        void dfs(int index, java.util.Set<String> used, int count) {
            if (index == s.length()) {
                if (count > max[0]) max[0] = count;
                return;
            }
            for (int len = 1; index + len <= s.length(); len++) {
                String sub = s.substring(index, index + len);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(index + len, used, count + 1);
                    used.remove(sub);
                }
            }
        }
    }
    new Solver().dfs(0, new java.util.HashSet<>(), 0);
    return max[0];
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in the same folder, do nothing
        } else if (log.endsWith("/") && !log.equals("./") && !log.equals("../")) {
            // assume it's a valid folder name
            depth++;
        }
        // any other string is ignored
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: the minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    // Start with all 'a's
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // extra value to distribute
    // Distribute from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase by at most 25
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

