public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    Queue<Long> queue = new LinkedList<>();
    // Handle 0 separately
    if (low == 0) {
        result.add(0);
    }
    // Initialize queue with single digit numbers 1-9
    for (int d = 1; d <= 9; d++) {
        if (d >= low && d <= high) {
            result.add(d);
        }
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Generate next possible digits
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int next : nextDigits) {
            if (next < 0 || next > 9) {
                continue;
            }
            long newNum = num * 10 + next;
            if (newNum > high) {
                continue;
            }
            if (newNum >= low) {
                result.add((int) newNum);
            }
            queue.offer(newNum);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

