public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;
    // dp[i][j][k] where k: 0-horizontal, 1-vertical, 2-diagonal, 3-anti-diagonal
    int[][][] dp = new int[m][n][4];
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            // Handle non-rectangular matrix gracefully
            return 0;
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                       Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                dp[i][j][0] = dp[i][j][1] = dp[i][j][2] = dp[i][j][3] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numStr = String.valueOf(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to correct order
    sb.reverse();

    // Prepend negative sign if needed
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) return 0;
    int n = A.length;
    if (n == 0) return 1;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    // Precompute adjacency matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            can[i][j] = sqrt * sqrt == sum;
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            if (mask == fullMask) return 1;
            int memo = dp[mask][last];
            if (memo != -1) return memo;
            int count = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!can[last][next]) continue;
                // Skip duplicates: if next > 0, same value as previous and previous not used
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << next), next);
            }
            dp[mask][last] = count;
            return count;
        }
    };
    int result = 0;
    for (int start = 0; start < n; start++) {
        // Skip duplicates for first element
        if (start > 0 && A[start] == A[start - 1]) continue;
        result += dfs.applyAsInt(1 << start, start);
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? n : n - stack.peek() - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        for (int i = 0; i < m; i++) {
            int j = sum - i;
            if (j >= 0 && j < n) {
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find pivot: the first index from the right where digits[i] < digits[i+1]
    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }
    if (pivot == -1) {
        // No higher permutation exists
        return -1;
    }
    // Find the smallest digit greater than pivot in the suffix
    int successor = -1;
    for (int j = len - 1; j > pivot; j--) {
        if (digits[j] > digits[pivot]) {
            successor = j;
            break;
        }
    }
    // Swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;
    // Reverse the suffix starting at pivot+1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to number
    long result;
    try {
        result = Long.parseLong(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

